// tokenbucket.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is the time source used by the bucket.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Bucket is a concurrency-safe token-bucket rate limiter.
type Bucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	clock    Clock
	last     time.Time
}

// New returns a Bucket allowing up to capacity tokens, refilling at ratePerSecond.
func New(capacity int, ratePerSecond float64, clock Clock) (*Bucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if ratePerSecond <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	now := clock.Now()
	return &Bucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     ratePerSecond,
		clock:    clock,
		last:     now,
	}, nil
}

// NewReal returns a Bucket using the system clock.
func NewReal(capacity int, ratePerSecond float64) (*Bucket, error) {
	return New(capacity, ratePerSecond, realClock{})
}

func (b *Bucket) refillLocked(now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}

// AllowN reports whether n tokens are available and consumes them if so.
// n <= 0 is always allowed and consumes nothing.
func (b *Bucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	now := b.clock.Now()
	b.refillLocked(now)
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token is available and consumes it if so.
func (b *Bucket) Allow() bool {
	return b.AllowN(1)
}

// Remaining returns the whole number of tokens currently available.
func (b *Bucket) Remaining() int {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked(b.clock.Now())
	return int(b.tokens)
}

// Capacity returns the configured maximum token count.
func (b *Bucket) Capacity() int {
	return int(b.capacity)
}
