package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.now
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.now = f.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := newFakeClock()
	tests := []struct {
		name    string
		cap     int
		rate    float64
		clock   Clock
		wantErr bool
	}{
		{"nil clock", 10, 1, nil, true},
		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 10, 0, clock, true},
		{"negative rate", 10, -1, clock, true},
		{"valid", 10, 2, clock, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := New(tt.cap, tt.rate, tt.clock)
			if tt.wantErr {
				if err == nil {
					t.Fatal("expected error, got nil")
				}
				if b != nil {
					t.Fatal("expected nil bucket on error")
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name   string
		cap    int
		rate   float64
		steps  []step
		wantOK []bool
	}{
		{
			name: "consumes and denies when empty",
			cap:  2, rate: 1,
			steps:  []step{{0, 1}, {0, 1}, {0, 1}},
			wantOK: []bool{true, true, false},
		},
		{
			name: "refills over time",
			cap:  2, rate: 2,
			steps:  []step{{0, 2}, {500 * time.Millisecond, 1}},
			wantOK: []bool{true, true},
		},
		{
			name: "caps refill at capacity",
			cap:  2, rate: 10,
			steps:  []step{{0, 2}, {time.Hour, 2}},
			wantOK: []bool{true, true},
		},
		{
			name: "zero and negative n always allowed",
			cap:  1, rate: 1,
			steps:  []step{{0, 0}, {0, -5}},
			wantOK: []bool{true, true},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := newFakeClock()
			b, err := New(tt.cap, tt.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tt.steps {
				clock.Advance(s.advance)
				if got := b.AllowN(s.n); got != tt.wantOK[i] {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, tt.wantOK[i])
				}
			}
		})
	}
}

type step struct {
	advance time.Duration
	n       int
}

func TestRemainingAndCapacity(t *testing.T) {
	clock := newFakeClock()
	b, err := New(5, 1, clock)
	if err != nil {
		t.Fatal(err)
	}
	if b.Capacity() != 5 {
		t.Fatalf("Capacity() = %d, want 5", b.Capacity())
	}
	if b.Remaining() != 5 {
		t.Fatalf("Remaining() = %d, want 5", b.Remaining())
	}
	b.AllowN(2)
	clock.Advance(1500 * time.Millisecond)
	if got := b.Remaining(); got != 4 {
		t.Fatalf("Remaining() = %d, want 4", got)
	}
}

func TestConcurrentAllow(t *testing.T) {
	clock := newFakeClock()
	b, err := New(100, 1000, clock)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100", allowed)
	}
}
