type Limiter struct {
	mu      sync.Mutex
	capacity float64
	rate    float64
	tokens  float64
	last    time.Time
	clock   Clock
}

func New(capacity int, refillPerSecond float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if refillPerSecond <= 0 {
		return nil, errors.New("ratelimit: refill rate must be positive")
	}
	now := clock.Now()
	return &Limiter{
		capacity: float64(capacity),
		rate:     refillPerSecond,
		tokens:   float64(capacity),
		last:     now,
		clock:    clock,
	}, nil
}

func NewDefault(capacity int, refillPerSecond float64) (*Limiter, error) {
	return New(capacity, refillPerSecond, realClock{})
}

func (l *Limiter) Allow() bool { return l.AllowN(1) }

func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refillLocked()
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refillLocked()
	return l.tokens
}

func (l *Limiter) refillLocked() {
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = now
}
