				t.Fatal("expected limiter")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	type step struct {
		advance time.Duration
		n       int
		want    bool
	}
	tests := []struct {
		name     string
		capacity int
		rate     float64
		steps    []step
	}{
		{
			name:     "drains and refills",
			capacity: 5,
			rate:     1,
			steps: []step{
				{0, 5, true},
				{0, 1, false},
